// MONOLITH: Single transaction across tables
@Transactional
public Order createOrder(OrderRequest request) {
    var order = orderRepository.save(new Order(request));
    inventoryRepository.decreaseStock(request.productId(), request.quantity());
    paymentRepository.createCharge(order.id(), request.amount());
    return order; // All-or-nothing: automatic rollback on failure
}

// MICROSERVICES: Each service is a separate network call
public Order createOrder(OrderRequest request) {
    var order = orderRepository.save(new Order(request));

    // Call to Inventory microservice - could fail
    var inventoryResponse = inventoryClient.decreaseStock(request.productId(), request.quantity());
    if (!inventoryResponse.isSuccess()) {
        orderRepository.delete(order); // Manual compensation
        throw new OutOfStockException();
    }

    // Call to Payment microservice - could timeout
    var paymentResponse = paymentClient.charge(order.id(), request.amount());
    if (!paymentResponse.isSuccess()) {
        inventoryClient.restoreStock(request.productId(), request.quantity()); // Compensating transaction
        orderRepository.delete(order);
        throw new PaymentFailedException();
    }

    return order; // No automatic rollback - you handle failures
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    private final OrderService orderService;
    private final InventoryClient inventoryClient; // Calls another microservice

    @PostMapping
    public ResponseEntity<OrderResponse> createOrder(@RequestBody OrderRequest request) {
        // Your team owns Order service logic
        var availableStock = inventoryClient.checkStock(request.productId());
        if (availableStock < request.quantity()) {
            return ResponseEntity.badRequest().body(new OrderResponse("Out of stock"));
        }

        var order = orderService.create(request); // Your service's database
        return ResponseEntity.ok(new OrderResponse(order.id(), "Order created"));
    }
}

@Service
class InventoryClient {
    private final RestTemplate restTemplate;

    public int checkStock(Long productId) {
        // Call to Inventory microservice owned by another team
        var url = "http://inventory-service/api/products/" + productId + "/stock";
        return restTemplate.getForObject(url, Integer.class); // Network call - could fail
    }
}
